#!/usr/bin/env python3
"""Deterministic board utilities for the agent-workflow control plane.

No third-party dependencies (stdlib tomllib). This is the part of the nightly
pipeline that must NOT be an LLM: parsing, validation, dependency/seam
partitioning, claiming, and status transitions are reproducible code.

Usage:
  board.py list        [--project P | --file F] [--status S] [--json]
  board.py validate    [--project P | --file F]
  board.py partition   [--project P | --file F] [--json]
  board.py next        [--project P] [--json]
  board.py set-status  --id ID --status STATUS [--project P | --file F]

Board grammar (one block per task; superset of the old val2-tasks.md):

    ## [04] Replace the reconcile-claim watchdog
    project: vea-validator2
    seam: src/tasks/mod.rs, src/contracts.rs
    deps: none
    risk: high
    workers: writer=claude-code, reviewer=pi:val2-tester
    status: todo
    acceptance: |
        cargo build --all-targets passes
    description: |
        Free-form, multi-line task text.
"""

from __future__ import annotations

import argparse
import json
import os
import re
import sys
import tempfile
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TASKS_DIR = ROOT / "tasks"
REGISTRY = ROOT / "projects.toml"

BLOCK_RE = re.compile(r"^##\s*\[([^\]]+)\]\s*(.*)$")
FIELD_RE = re.compile(r"^([A-Za-z_][A-Za-z0-9_]*):\s?(.*)$")
LIST_FIELDS = {"seam", "deps", "risk"}


@dataclass
class Task:
    id: str
    title: str
    fields: dict[str, str] = field(default_factory=dict)
    source: str = ""
    lineno: int = 0

    @property
    def project(self) -> str:
        return self.fields.get("project", "")

    @property
    def status(self) -> str:
        return self.fields.get("status", "todo")

    @property
    def seam(self) -> list[str]:
        return _split(self.fields.get("seam", ""))

    @property
    def deps(self) -> list[str]:
        return [d for d in _split(self.fields.get("deps", "")) if d.lower() != "none"]

    @property
    def workers(self) -> dict[str, str]:
        out: dict[str, str] = {}
        for pair in _split(self.fields.get("workers", "")):
            if "=" in pair:
                k, v = pair.split("=", 1)
                out[k.strip()] = v.strip()
        return out

    @property
    def is_risky(self) -> bool:
        return self.fields.get("risk", "").lower() in {"high", "critical"}

    def to_dict(self) -> dict:
        return {
            "id": self.id,

            "id": self.id,
            "title": self.title,
            "project": self.project,
            "status": self.status,
            "seam": self.seam,
            "deps": self.deps,
            "risk": self.fields.get("risk", ""),
            "workers": self.workers,
            "acceptance": self.fields.get("acceptance", ""),
            "description": self.fields.get("description", ""),
            "source": self.source,
            "lineno": self.lineno,
        }


def _split(value: str) -> list[str]:
    return [p.strip() for p in value.split(",") if p.strip()]


def _natkey(task_id: str):
    parts = re.split(r"(\d+)", task_id)
    return tuple((0, int(p)) if p.isdigit() else (1, p) for p in parts)


def parse_board(path: Path) -> list[Task]:
    """Parse one board file into tasks. Multi-line `key: |` values supported.

    HTML comments (`<!-- ... -->`) are ignored, so boards can carry commented
    examples without them being picked up as tasks.
    """
    text = re.sub(
        r"<!--.*?-->",
        lambda m: re.sub(r"[^\n]", " ", m.group(0)),
        path.read_text(),
        flags=re.S,
    )
    lines = text.splitlines()
    tasks: list[Task] = []
    cur: Task | None = None
    i = 0
    while i < len(lines):
        line = lines[i]
        m = BLOCK_RE.match(line)
        if m:
            cur = Task(id=m.group(1).strip(), title=m.group(2).strip(), source=str(path), lineno=i + 1)
            tasks.append(cur)
            i += 1
            continue
        if cur is not None:
            fm = FIELD_RE.match(line)
            if fm:
                key, value = fm.group(1), fm.group(2)
                if value.strip() == "|":
                    block: list[str] = []
                    i += 1
                    while i < len(lines):
                        nxt = lines[i]
                        if nxt.strip() and not nxt.startswith((" ", "\t")):
                            break
                        block.append(nxt)
                        i += 1
                    cur.fields[key] = _dedent(block).strip("\n")
                    continue
                cur.fields[key] = value.strip()
            elif line.strip() == "---":
                cur = None
        i += 1
    return tasks


def _dedent(block: list[str]) -> str:
    indents = [len(l) - len(l.lstrip()) for l in block if l.strip()]
    strip = min(indents) if indents else 0
    return "\n".join(l[strip:] if l.strip() else "" for l in block)


def board_files(project: str | None, explicit: str | None) -> list[Path]:
    if explicit:
        p = Path(explicit)
        if not p.is_absolute():
            p = ROOT / p
        return [p]
    if project:
        p = TASKS_DIR / f"{project}.md"
        if not p.exists():
            raise SystemExit(f"no board for project {project!r}: {p}")
        return [p]
    return sorted(TASKS_DIR.glob("*.md"))


def load_tasks(project: str | None, explicit: str | None) -> list[Task]:
    tasks: list[Task] = []
    for path in board_files(project, explicit):
        tasks.extend(parse_board(path))
    tasks.sort(key=lambda t: _natkey(t.id))
    return tasks


def load_registry() -> dict:
    if not REGISTRY.exists():
        return {}
    with REGISTRY.open("rb") as fh:
        return tomllib.load(fh)


def validate(tasks: list[Task]) -> list[str]:
    errors: list[str] = []
    registry = load_registry()
    known_projects = {k for k in registry if k != "defaults"}
    ids: dict[str, Task] = {}
    for t in tasks:
        if t.id in ids:
            errors.append(f"duplicate id [{t.id}] in {t.source}:{t.lineno} and {ids[t.id].source}:{ids[t.id].lineno}")
        ids[t.id] = t
        if not t.project:
            errors.append(f"[{t.id}] missing `project:`")
        elif t.project not in known_projects:
            errors.append(f"[{t.id}] unknown project {t.project!r} (not in projects.toml)")
        if not t.fields.get("seam"):
            errors.append(f"[{t.id}] missing `seam:`")
        if not t.fields.get("description"):
            errors.append(f"[{t.id}] missing `description:`")
    for t in tasks:
        for dep in t.deps:
            if dep not in ids:
                errors.append(f"[{t.id}] deps names unknown task [{dep}]")
    return errors


def partition(tasks: list[Task]) -> list[list[str]]:
    """Group tasks into ordered parallel batches.

    An edge A -> B exists if B depends on A, or A and B share a seam (lower id
    first). Tasks in the same batch have no path between them and may run in
    parallel. Batches themselves are sequential (batch N integrates before N+1).
    """
    by_id = {t.id: t for t in tasks}
    ids = [_natkey(t.id) for t in tasks]
    order = [t.id for t in sorted(tasks, key=lambda t: _natkey(t.id))]
    edges: dict[str, set[str]] = {t.id: set() for t in tasks}
    indeg: dict[str, int] = {t.id: 0 for t in tasks}

    def add_edge(a: str, b: str) -> None:
        if a == b or b in edges[a]:
            return
        edges[a].add(b)
        indeg[b] += 1

    for t in tasks:
        for dep in t.deps:
            if dep in by_id:
                add_edge(dep, t.id)
    for i, a in enumerate(order):
        for b in order[i + 1:]:
            if set(by_id[a].seam) & set(by_id[b].seam):
                add_edge(a, b)

    level: dict[str, int] = {}
    ready = [tid for tid in order if indeg[tid] == 0]
    processed = 0
    remaining = dict(indeg)
    queue = list(ready)
    while queue:
        tid = queue.pop(0)
        processed += 1
        for nxt in sorted(edges[tid], key=_natkey):  # noqa: E501
            level[nxt] = max(level.get(nxt, 0), level.get(tid, 0) + 1)
            remaining[nxt] -= 1
            if remaining[nxt] == 0:
                queue.append(nxt)
    if processed != len(tasks):
        raise SystemExit("dependency/seam graph has a cycle; cannot partition")

    groups: dict[int, list[str]] = {}
    for tid in order:
        groups.setdefault(level.get(tid, 0), []).append(tid)
    return [groups[k] for k in sorted(groups)]


def _atomic_write(path: Path, text: str) -> None:
    fd, tmp = tempfile.mkstemp(dir=str(path.parent))
    try:
        with os.fdopen(fd, "w") as fh:
            fh.write(text)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


def set_status(task: Task, status: str) -> None:
    path = Path(task.source)
    lines = path.read_text().splitlines(keepends=True)
    start = task.lineno - 1
    for i in range(start, len(lines)):
        if BLOCK_RE.match(lines[i]) and i != start:
            break
        if FIELD_RE.match(lines[i]) and lines[i].startswith("status:"):
            nl = "\n" if lines[i].endswith("\n") else ""
            lines[i] = f"status: {status}{nl}"
            break
    else:
        raise SystemExit(f"no status line found for [{task.id}] in {path}")
    _atomic_write(path, "".join(lines))


def delete_task(task: Task) -> None:
    """Remove a task block: its header through the line before the next block."""
    path = Path(task.source)
    lines = path.read_text().splitlines(keepends=True)
    start = task.lineno - 1
    if not (0 <= start < len(lines) and BLOCK_RE.match(lines[start])):
        start = next(
            (i for i, l in enumerate(lines) if BLOCK_RE.match(l) and l.startswith(f"## [{task.id}]")),
            -1,
        )
    if start < 0:
        raise SystemExit(f"cannot locate task [{task.id}] in {path}")
    end = next((i for i in range(start + 1, len(lines)) if BLOCK_RE.match(lines[i])), len(lines))
    del lines[start:end]
    _atomic_write(path, re.sub(r"\n{3,}", "\n\n", "".join(lines)))


def _emit(obj, as_json: bool) -> None:
    if as_json:
        print(json.dumps(obj, indent=2))
    else:
        print(obj)


def cmd_list(args) -> None:
    tasks = load_tasks(args.project, args.file)
    if args.status:
        tasks = [t for t in tasks if t.status == args.status]
    if args.json:
        _emit([t.to_dict() for t in tasks], True)
    else:
        for t in tasks:
            print(f"[{t.id}] {t.title}  ({t.project}, {t.status})")


def cmd_validate(args) -> None:
    tasks = load_tasks(args.project, args.file)
    errors = validate(tasks)
    if errors:
        for e in errors:
            print(f"ERROR: {e}", file=sys.stderr)
        raise SystemExit(1)
    print(f"OK: {len(tasks)} task(s) valid")


def cmd_partition(args) -> None:
    tasks = load_tasks(args.project, args.file)
    errors = validate(tasks)
    if errors:
        for e in errors:
            print(f"ERROR: {e}", file=sys.stderr)
        raise SystemExit(1)
    groups = partition(tasks)
    if args.json:
        _emit(groups, True)
        return
    print("batch | tasks")
    for i, group in enumerate(groups, 1):
        print(f"{i:>5} | {', '.join(group)}")


def cmd_next(args) -> None:
    all_tasks = load_tasks(args.project, args.file)
    errors = validate(all_tasks)
    if errors:
        for e in errors:
            print(f"ERROR: {e}", file=sys.stderr)
        raise SystemExit(1)
    tasks = [t for t in all_tasks if t.status == "todo"]
    groups = partition(tasks)
    if not groups:
        _emit([], args.json)
        return
    if args.json:
        _emit(groups[0], True)
    else:
        print(", ".join(groups[0]))


def cmd_set_status(args) -> None:
    tasks = load_tasks(args.project, args.file)
    matches = [t for t in tasks if t.id == args.id]
    if not matches:
        raise SystemExit(f"task [{args.id}] not found")
    set_status(matches[0], args.status)
    print(f"[{args.id}] -> {args.status}")


def main() -> None:
    p = argparse.ArgumentParser(description="agent-workflow board utilities")
    sub = p.add_subparsers(dest="cmd", required=True)

    def common(sp):
        sp.add_argument("--project")
        sp.add_argument("--file")
        sp.add_argument("--json", action="store_true")

    sp = sub.add_parser("list")
    common(sp)
    sp.add_argument("--status")
    sp.set_defaults(func=cmd_list)

    sp = sub.add_parser("validate")
    common(sp)
    sp.set_defaults(func=cmd_validate)

    sp = sub.add_parser("partition")
    common(sp)
    sp.set_defaults(func=cmd_partition)

    sp = sub.add_parser("next")
    common(sp)
    sp.set_defaults(func=cmd_next)

    sp = sub.add_parser("set-status")
    common(sp)
    sp.add_argument("--id", required=True)
    sp.add_argument("--status", required=True)
    sp.set_defaults(func=cmd_set_status)

    args = p.parse_args()
    args.func(args)


if __name__ == "__main__":
    main()

