def set_scheduled(task: Task, scheduled: bool) -> None:
    """Set (or insert) the `scheduled:` line of a task block."""
    path = Path(task.source)
    lines = path.read_text().splitlines(keepends=True)
    start = task.lineno - 1
    value = "yes" if scheduled else "no"
    for i in range(start, len(lines)):
        if BLOCK_RE.match(lines[i]) and i != start:
            break
        fm = FIELD_RE.match(lines[i])
        if fm and lines[i].startswith("scheduled:"):
            nl = "\n" if lines[i].endswith("\n") else ""
            lines[i] = f"scheduled: {value}{nl}"
            break
    else:
        insert_at = None
        for i in range(start, len(lines)):
            if BLOCK_RE.match(lines[i]) and i != start:
                break
            if FIELD_RE.match(lines[i]) and lines[i].startswith("status:"):
                insert_at = i
                break
        if insert_at is None:
            raise SystemExit(f"no status line found for [{task.id}] in {path}")
        nl = "\n" if lines[insert_at].endswith("\n") else ""
        lines.insert(insert_at + 1, f"scheduled: {value}{nl}")
    _atomic_write(path, "".join(lines))

