  if (!r.ok || /^COMMIT-FAILED/m.test(r.output || "")) { results.push({ id: t.id, stage: "commit-failed", commitOk: r.ok, commit: r.output }); return; }
  results.push({ id: t.id, stage: "complete", verdict: t.verdict, commit: r.output });
});
return results;
